INSERT INTO org_units (code, tenant_id, name, short_name, type, parent_id, created_at, updated_at)
SELECT code, tenant_id, name, short_name, 'College', NULL, created_at, updated_at
FROM colleges;

INSERT INTO schedulable_units (code, tenant_id, title, unit, batched, shared, general, expected_class_size, created_at, updated_at)
SELECT code, tenant_id, course_title, course_unit, batched, shared, general, expected_class_size, created_at, updated_at
FROM courses;
